changeSet.sql:
CREATE OR REPLACE FUNCTION nexus_test.analyze_table(target regclass) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ANALYZE %s', target);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.add_fk_not_valid(
    p_table regclass, p_name text, p_column text, p_ref regclass, p_ref_column text, p_extra text
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (tenant_id, %I) REFERENCES %s (tenant_id, %I) %s NOT VALID',
        p_table, p_name, p_column, p_ref, p_ref_column, p_extra);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.validate_constraint(p_table regclass, p_name text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s VALIDATE CONSTRAINT %I', p_table, p_name);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.set_force_rls(p_table regclass, p_force boolean) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    IF p_force THEN
        EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    ELSE
        EXECUTE format('ALTER TABLE %s NO FORCE ROW LEVEL SECURITY', p_table);
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.set_row_security(p_table regclass, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    IF p_enabled THEN
        EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    ELSE
        EXECUTE format('ALTER TABLE %s DISABLE ROW LEVEL SECURITY', p_table);
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.drop_policy(p_table regclass, p_policy text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('DROP POLICY %I ON %s', p_policy, p_table);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.widen_policy(p_table regclass, p_policy text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER POLICY %I ON %s USING (true)', p_policy, p_table);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.add_permissive_policy(p_table regclass, p_policy text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('CREATE POLICY %I ON %s FOR SELECT USING (true)', p_policy, p_table);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.reset_tenant_policy(p_table regclass) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %s', p_table);
    EXECUTE format('CREATE POLICY tenant_isolation ON %s USING (tenant_id = current_setting(''nexus.tenant'', true)) WITH CHECK (tenant_id = current_setting(''nexus.tenant'', true))', p_table);
END;
$$;

changeSet.rollback:
DROP FUNCTION IF EXISTS nexus_test.set_row_security(regclass, boolean);
DROP FUNCTION IF EXISTS nexus_test.drop_policy(regclass, text);
DROP FUNCTION IF EXISTS nexus_test.widen_policy(regclass, text);
DROP FUNCTION IF EXISTS nexus_test.add_permissive_policy(regclass, text);
DROP FUNCTION IF EXISTS nexus_test.reset_tenant_policy(regclass);

changeSet.sql:
CREATE OR REPLACE FUNCTION nexus_test.drop_constraint(p_table regclass, p_name text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', p_table, p_name);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.add_fk_not_valid_composite3(
    p_table regclass, p_name text, p_col2 text, p_col3 text,
    p_ref regclass, p_ref_col2 text, p_ref_col3 text, p_extra text
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (tenant_id, %I, %I) REFERENCES %s (tenant_id, %I, %I) %s NOT VALID',
        p_table, p_name, p_col2, p_col3, p_ref, p_ref_col2, p_ref_col3, p_extra);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.add_fk_not_valid_composite3(
    p_table regclass, p_name text, p_col2 text, p_col3 text,
    p_ref regclass, p_ref_col2 text, p_ref_col3 text, p_extra text
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_cols     text := format('tenant_id, %I, %I', p_col2, p_col3);
    v_ref_cols text := format('tenant_id, %I, %I', p_ref_col2, p_ref_col3);
BEGIN
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = p_table AND a.attname = 'embedding_model' AND NOT a.attisdropped)
       AND EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = p_ref AND a.attname = 'embedding_model' AND NOT a.attisdropped) THEN
        v_cols := v_cols || ', embedding_model';
        v_ref_cols := v_ref_cols || ', embedding_model';
    END IF;
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (%s) REFERENCES %s (%s) %s NOT VALID',
        p_table, p_name, v_cols, p_ref, v_ref_cols, p_extra);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.grant_execute_on_function(p_signature text, p_role text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', p_signature, p_role);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.insert_chunk_bare_vector(
    p_tenant text, p_collection text, p_chash bytea, p_dim int
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_lit text;
BEGIN
    SELECT '[' || string_agg('0.1', ',') || ']' INTO v_lit FROM generate_series(1, p_dim);
    EXECUTE format(
        'INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, %I) VALUES ($1, $2, $3, $4, $5::vector)',
        'embedding_' || p_dim)
        USING p_tenant, p_collection, p_chash, 'text', v_lit;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.insert_chunk_bare_vector(
    p_tenant text, p_collection text, p_chash bytea, p_dim int
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_lit   text;
    v_model text;
BEGIN
    SELECT '[' || string_agg('0.1', ',') || ']' INTO v_lit FROM generate_series(1, p_dim);
    IF EXISTS (SELECT 1 FROM information_schema.columns
                WHERE table_schema = 'nexus' AND table_name = 'chunks' AND column_name = 'embedding_model') THEN
        SELECT c.embedding_model INTO v_model
          FROM nexus.catalog_collections c
         WHERE c.tenant_id = p_tenant AND c.name = p_collection;
        IF v_model IS NULL THEN
            RAISE EXCEPTION 'nexus_test.insert_chunk_bare_vector: collection % is not registered for tenant % (a chunk carries its collection''s model)',
                p_collection, p_tenant;
        END IF;
        EXECUTE format(
            'INSERT INTO nexus.chunks (tenant_id, collection, chash, embedding_model, chunk_text, %I) VALUES ($1, $2, $3, $4, $5, $6::vector)',
            'embedding_' || p_dim)
            USING p_tenant, p_collection, p_chash, v_model, 'text', v_lit;
    ELSE
        EXECUTE format(
            'INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, %I) VALUES ($1, $2, $3, $4, $5::vector)',
            'embedding_' || p_dim)
            USING p_tenant, p_collection, p_chash, 'text', v_lit;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.drop_index(p_index regclass) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_schema text;
    v_name   text;
BEGIN
    SELECT n.nspname, c.relname INTO STRICT v_schema, v_name
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_index;
    EXECUTE format('DROP INDEX %I.%I', v_schema, v_name);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.p225_ts3_delete_and_reinsert(p_tenant text, p_collection text, p_chash bytea) RETURNS integer
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_row record;
BEGIN
    SET CONSTRAINTS nexus.fk_catalog_chunks_chunk DEFERRED;
    SELECT * INTO v_row FROM nexus.chunks c
     WHERE c.tenant_id = p_tenant AND c.collection = p_collection AND c.chash = p_chash;
    IF NOT FOUND THEN
        RETURN 0;
    END IF;
    DELETE FROM nexus.chunks c
     WHERE c.tenant_id = p_tenant AND c.collection = p_collection AND c.chash = p_chash;
    INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024,
                              metadata, created_at, retention, last_written_at, embedding_model)
    VALUES (v_row.tenant_id, v_row.collection, v_row.chash, v_row.chunk_text, v_row.embedding_384, v_row.embedding_768,
            v_row.embedding_1024, v_row.metadata, v_row.created_at, v_row.retention, v_row.last_written_at,
            v_row.embedding_model);
    RETURN 1;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.p225_ts3_delete_only(p_tenant text, p_collection text, p_chash bytea) RETURNS integer
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_n integer;
BEGIN
    SET CONSTRAINTS nexus.fk_catalog_chunks_chunk DEFERRED;
    DELETE FROM nexus.chunks c
     WHERE c.tenant_id = p_tenant AND c.collection = p_collection AND c.chash = p_chash;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.p225_seed_random_chunks(
    p_tenant text, p_collection text, p_model text, p_dim int, p_n int
) RETURNS bigint
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_n bigint;
BEGIN
    EXECUTE format(
        'INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, %I, embedding_model) '
        'SELECT $1, $2, sha256(convert_to($1 || $2 || g::text, ''UTF8'')), ''seeded'', '
        '       (SELECT (''['' || string_agg(random()::text, '','') || '']'')::nexus.vector FROM generate_series(1, $3) WHERE g IS NOT NULL), $4 '
        '  FROM generate_series(1, $5) AS g',
        'embedding_' || p_dim)
        USING p_tenant, p_collection, p_dim, p_model, p_n;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.p225_explain_knn(p_tenant text, p_model text, p_dim int) RETURNS text
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_lit  text;
    v_line text;
    v_out  text := '';
BEGIN
    SELECT '[' || string_agg('0.1', ',') || ']' INTO v_lit FROM generate_series(1, p_dim);
    FOR v_line IN EXECUTE format(
        'EXPLAIN (COSTS OFF) SELECT chash FROM nexus.chunks WHERE tenant_id = %L AND embedding_model = %L '
        'ORDER BY %I OPERATOR(nexus.<=>) %L::nexus.vector LIMIT 10',
        p_tenant, p_model, 'embedding_' || p_dim, v_lit)
    LOOP
        v_out := v_out || v_line || E'\n';
    END LOOP;
    RETURN v_out;
END;
$$;
